const listCashAccountMovements = `-- name: ListCashAccountMovements :many
SELECT id, uuid, kind, direction, amount, currency, movement_date, description, transfer_group, source_type, source_uuid, created_at, counter_account_uuid, counter_account_name, reverses_uuid, reversed_by_uuid, closing_uuid, creator_uuid, creator_name, creator_surname, running_total FROM (
    SELECT
        m.id, m.uuid, m.kind, m.direction, m.amount, m.currency, m.movement_date, m.description,
        m.transfer_group, m.source_type, m.source_uuid, m.created_at,
        ca.uuid AS counter_account_uuid, ca.name AS counter_account_name,
        rv.uuid AS reverses_uuid, rb.uuid AS reversed_by_uuid, cl.uuid AS closing_uuid,
        u.uuid AS creator_uuid, u.name AS creator_name, u.surname AS creator_surname,
        (SUM(CASE WHEN m.direction = 'in' THEN m.amount ELSE -m.amount END)
            OVER (ORDER BY m.movement_date, m.id))::numeric AS running_total
    FROM cash_movements m
    LEFT JOIN cash_accounts ca ON ca.organization_id = m.organization_id AND ca.id = m.counter_account_id
    LEFT JOIN cash_movements rv ON rv.organization_id = m.organization_id AND rv.id = m.reverses_movement_id
    LEFT JOIN cash_movements rb ON rb.organization_id = m.organization_id AND rb.reverses_movement_id = m.id
    LEFT JOIN cash_closings cl ON cl.organization_id = m.organization_id AND cl.id = m.closing_id
    LEFT JOIN users u ON u.id = m.created_by
    WHERE m.organization_id = $1
      AND m.cash_account_id = $2
) t
WHERE ($3::date IS NULL OR t.movement_date >= $3::date)
  AND ($4::date IS NULL OR t.movement_date <= $4::date)
  AND ($5::text[] IS NULL OR t.kind = ANY($5::text[]))
ORDER BY t.movement_date DESC, t.id DESC
LIMIT $7 OFFSET $6
`

type ListCashAccountMovementsParams struct {
	OrganizationID int64       `json:"organization_id"`
	CashAccountID  int64       `json:"cash_account_id"`
	DateFrom       pgtype.Date `json:"date_from"`
	DateTo         pgtype.Date `json:"date_to"`
	Kinds          []string    `json:"kinds"`
	OffsetCount    int32       `json:"offset_count"`
	LimitCount     int32       `json:"limit_count"`
}

type ListCashAccountMovementsRow struct {
	ID                 int64              `json:"id"`
	Uuid               uuid.UUID          `json:"uuid"`
	Kind               string             `json:"kind"`
	Direction          string             `json:"direction"`
	Amount             pgtype.Numeric     `json:"amount"`
	Currency           string             `json:"currency"`
	MovementDate       pgtype.Date        `json:"movement_date"`
	Description        string             `json:"description"`
	TransferGroup      pgtype.UUID        `json:"transfer_group"`
	SourceType         string             `json:"source_type"`
	SourceUuid         pgtype.UUID        `json:"source_uuid"`
	CreatedAt          pgtype.Timestamptz `json:"created_at"`
	CounterAccountUuid pgtype.UUID        `json:"counter_account_uuid"`
	CounterAccountName pgtype.Text        `json:"counter_account_name"`
	ReversesUuid       pgtype.UUID        `json:"reverses_uuid"`
	ReversedByUuid     pgtype.UUID        `json:"reversed_by_uuid"`
	ClosingUuid        pgtype.UUID        `json:"closing_uuid"`
	CreatorUuid        pgtype.UUID        `json:"creator_uuid"`
	CreatorName        pgtype.Text        `json:"creator_name"`
	CreatorSurname     pgtype.Text        `json:"creator_surname"`
	RunningTotal       pgtype.Numeric     `json:"running_total"`
}

// The movements of one account with the balance after each one (book
// order: date, then entry order), newest first.
func (q *Queries) ListCashAccountMovements(ctx context.Context, arg ListCashAccountMovementsParams) ([]ListCashAccountMovementsRow, error) {
	rows, err := q.db.Query(ctx, listCashAccountMovements,
		arg.OrganizationID,
		arg.CashAccountID,
		arg.DateFrom,
		arg.DateTo,
		arg.Kinds,
		arg.OffsetCount,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCashAccountMovementsRow{}
	for rows.Next() {
		var i ListCashAccountMovementsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.Kind,
			&i.Direction,
			&i.Amount,
			&i.Currency,
			&i.MovementDate,
			&i.Description,
			&i.TransferGroup,
			&i.SourceType,
			&i.SourceUuid,
			&i.CreatedAt,
			&i.CounterAccountUuid,
			&i.CounterAccountName,
			&i.ReversesUuid,
			&i.ReversedByUuid,
			&i.ClosingUuid,
			&i.CreatorUuid,
			&i.CreatorName,
			&i.CreatorSurname,
			&i.RunningTotal,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

