const listCashAccounts = `-- name: ListCashAccounts :many
SELECT
    a.id, a.uuid, a.organization_id, a.branch_id, a.kind, a.name, a.currency, a.opening_balance,
    a.opening_date, a.bank_name, a.iban, a.provider, a.note, a.status, a.sort_order, a.created_at, a.updated_at,
    b.uuid AS branch_uuid, b.name AS branch_name, b.code AS branch_code,
    bal.balance::numeric AS balance,
    (SELECT MAX(c.business_date) FROM cash_closings c
     WHERE c.organization_id = a.organization_id AND c.cash_account_id = a.id AND c.status = 'closed')::date AS last_closed_date
FROM cash_accounts a
LEFT JOIN branches b ON b.organization_id = a.organization_id AND b.id = a.branch_id
CROSS JOIN LATERAL (
    SELECT a.opening_balance + COALESCE(SUM(CASE WHEN m.direction = 'in' THEN m.amount ELSE -m.amount END), 0) AS balance
    FROM cash_movements m
    WHERE m.organization_id = a.organization_id AND m.cash_account_id = a.id
) bal
WHERE a.organization_id = $1
  AND ($2::bigint[] IS NULL OR a.branch_id = ANY($2::bigint[]))
  AND (
    ($3::bigint[] IS NULL AND NOT $4::boolean)
    OR a.branch_id = ANY($3::bigint[])
    OR ($4::boolean AND a.branch_id IS NULL)
  )
  AND ($5::text[] IS NULL OR a.kind = ANY($5::text[]))
  AND ($6::text[] IS NULL OR a.status = ANY($6::text[]))
  AND (
    $7::text IS NULL
    OR a.name ILIKE '%' || $7 || '%'
    OR a.bank_name ILIKE '%' || $7 || '%'
    OR a.iban ILIKE '%' || $7 || '%'
    OR b.name ILIKE '%' || $7 || '%'
  )
ORDER BY
  CASE WHEN $8::text = 'name' AND NOT $9::boolean THEN a.name END ASC,
  CASE WHEN $8::text = 'name' AND $9::boolean THEN a.name END DESC,
  CASE WHEN $8::text = 'kind' AND NOT $9::boolean THEN a.kind END ASC,
  CASE WHEN $8::text = 'kind' AND $9::boolean THEN a.kind END DESC,
  CASE WHEN $8::text = 'balance' AND NOT $9::boolean THEN bal.balance END ASC,
  CASE WHEN $8::text = 'balance' AND $9::boolean THEN bal.balance END DESC,
  CASE WHEN $8::text = 'status' AND NOT $9::boolean THEN a.status END ASC,
  CASE WHEN $8::text = 'status' AND $9::boolean THEN a.status END DESC,
  CASE WHEN $8::text = 'sort_order' AND NOT $9::boolean THEN a.sort_order END ASC,
  CASE WHEN $8::text = 'sort_order' AND $9::boolean THEN a.sort_order END DESC,
  CASE WHEN $8::text = 'created_at' AND NOT $9::boolean THEN a.created_at END ASC,
  CASE WHEN $8::text = 'created_at' AND $9::boolean THEN a.created_at END DESC,
  a.status ASC, b.name ASC NULLS FIRST, a.sort_order ASC, a.name ASC, a.id ASC
LIMIT $11 OFFSET $10
`

